export interface BankData {
  name: string;
  appId: string;
  totalRaters: number;
  ratings: { five: number; four: number; three: number; two: number; one: number };
  averageRating: number;
  horizontalScore: number;
  verticalScore: number;
  verticalScorePercent: number;
  volumeValue: number;
  lastMonthDownloads: number;
  lastMonthRaters: number;
  lastMonthComments: number;
  activityScore: number;
  finalScore: number;
  category: string;
}

export interface AppStoreBankData {
  name: string;
  appId: string;
  totalRaters: number;
  rating5: number;
  rating4: number;
  rating3: number;
  rating2: number;
  rating1: number;
  averageRating: number;
  horizontalScore: number;
  verticalScore: number;
  verticalScorePercent: number;
  volumeValue: number;
  totalValue: number;
  lastMonthDownloads: number;
  lastMonthRaters: number;
  lastMonthReviews: number;
  activityScore: number;
  finalScore: number;
  category: string;
}

